import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import styled from 'styled-components';

const HomePage = () => {
  const [lorries, setLorries] = useState([]);

  useEffect(() => {
    // Fetch lorry details from the backend API
    const fetchLorries = async () => {
      try {
        const response = await fetch('http://localhost:5001/api/lorry'); 
        const data = await response.json();
        setLorries(data);
      } catch (error) {
        console.error('Error fetching lorries:', error);
      }
    };

    fetchLorries();
  }, []);
  return (
    <HomePageContainer>
      <ContactNumber>Contact: 9443769338</ContactNumber>
      <Header>Sri-Murugan Rig Service</Header>
      <CardContainer>
        {lorries.map((lorry) => (
          <Card key={lorry.id}>
            <CardHeader>{lorry.ownerName}</CardHeader>
            <OwnerPic src={lorry.ownerPic || 'default-pic.jpg'} alt={`${lorry.ownerName}`} />
            <CardBody>
              <p>Registration Number: {lorry.registrationNumber}</p>
              <DashboardLink to={`/dashboard/${lorry.registrationNumber}`}>
                Go to Dashboard
              </DashboardLink>
            </CardBody>
          </Card>
        ))}
      </CardContainer>
    </HomePageContainer>
  );
};

export default HomePage;

// Styled Components
const HomePageContainer = styled.div`
  padding: 20px;
  text-align: center;
`;

const Header = styled.h1`
  margin: 20px 0;
`;

const ContactNumber = styled.div`
  position: absolute;
  top: 20px;
  right: 20px;
  font-size: 1.2em;
  color: #333;
`;

const CardContainer = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
`;

const Card = styled.div`
  background-color: #f9f9f9;
  border: 1px solid #ddd;
  border-radius: 8px;
  margin: 10px;
  padding: 15px;
  width: 250px; /* Adjust width as needed */
  box-shadow: 0 2px 5px rgba(0, 0, 0, 0.1);
  transition: transform 0.2s;

  &:hover {
    transform: scale(1.05);
  }
`;

const CardHeader = styled.div`
  font-size: 1.2em;
  margin-bottom: 10px;
`;

const OwnerPic = styled.img`
  width: 100%;
  height: auto;
  border-radius: 50%; /* Make the image circular */
`;

const CardBody = styled.div`
  margin-top: 10px;
`;

const DashboardLink = styled(Link)`
  display: inline-block;
  margin-top: 10px;
  padding: 8px 12px;
  background-color: #007bff;
  color: white;
  text-decoration: none;
  border-radius: 4px;

  &:hover {
    background-color: #0056b3;
  }
`;
